<?php require 'config.php';require_login();$s=$pdo->prepare('SELECT * FROM flights WHERE id=?');$s->execute([(int)($_GET['flight']??0)]);$f=$s->fetch();if(!$f)exit('Flight not found');$msg='';if($_SERVER['REQUEST_METHOD']==='POST' && $f['available_seats']>0){$pdo->beginTransaction();try{$q=$pdo->prepare('UPDATE flights SET available_seats=available_seats-1 WHERE id=? AND available_seats>0');$q->execute([$f['id']]);if(!$q->rowCount())throw new Exception('No seats available');$code='SB'.strtoupper(bin2hex(random_bytes(4)));$seat='S'.($f['total_seats']-$f['available_seats']+1);$q=$pdo->prepare('INSERT INTO bookings(user_id,flight_id,passenger_name,passenger_age,seat_no,amount,booking_code) VALUES(?,?,?,?,?,?,?)');$q->execute([$_SESSION['user_id'],$f['id'],trim($_POST['passenger_name']),(int)$_POST['age'],$seat,$f['fare'],$code]);$id=$pdo->lastInsertId();$pdo->commit();header('Location: payment.php?id='.$id);exit;}catch(Exception $e){$pdo->rollBack();$msg=$e->getMessage();}}?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>Passenger details</h1><p><?=h($msg)?></p><p><?=h($f['airline'])?>: <?=h($f['origin'])?> to <?=h($f['destination'])?> — ₹<?=h($f['fare'])?></p><form method="post"><label>Passenger name</label><input name="passenger_name" required><label>Age</label><input type="number" name="age" min="1" max="120" required><button>Continue to payment</button></form></div></div></body></html>